// /frontend-react/src/components/ProfilePage.js (FINAL CLEAN LIST LAYOUT)

import React, { useState } from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (remains the same) ---
const mockProfileData = {
    name: "LIM CHIN WEI",
    icNumber: "851020-07-5XXX",
    dateOfBirth: "20 / OCTOBER / 1985",
    address: "NO. 12, JALAN SAGA, KUALA LUMPUR",
    initialEmergencyContact: "CHIN YEE (012-3456789)", 
};

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    const profile = mockProfileData;
    
    const [emergencyContact, setEmergencyContact] = useState(profile.initialEmergencyContact);
    const [isEditing, setIsEditing] = useState(false);

    const handleSaveContact = () => {
        console.log("Profile Updated! New Emergency Contact:", emergencyContact);
        setIsEditing(false);
        alert(`Emergency contact saved as: ${emergencyContact}`);
    };

    // --- FINAL InfoCard Component (Clean Native List Style) ---
    const InfoCard = ({ title, value, isEditable = false }) => (
        <div style={{
            padding: '20px 0', // Controlled padding, only vertical
            margin: '0', // No margin between list items
            width: '100%',
            backgroundColor: '#fff',
            borderBottom: '1px solid #e0e0e0', // Very clean separator
            textAlign: 'left',
            position: 'relative', 
        }}>
            {/* Title (Label) - Muted color, aligned with native styles */}
            <p style={{ 
                fontSize: isEasyMode ? '20px' : '15px', 
                fontWeight: '600', 
                margin: '0 20px 5px 20px', // Horizontal margin added here
                color: isEditable ? 'darkorange' : '#6c757d'
            }}>
                {title.toUpperCase()}
            </p>
            
            {/* Value (Data Display/Input) */}
            {!isEditable && (
                <p style={{ 
                    fontSize: isEasyMode ? '32px' : '20px', // Clearer, slightly smaller font
                    fontWeight: 'bold',
                    margin: '0 20px', // Horizontal margin added here
                    color: '#333' 
                }}>
                    {value}
                </p>
            )}
            
            {/* Editable Input Field */}
            {isEditable && (
                <div style={{ padding: '0 20px' }}> {/* Padding wraps the input */}
                    <input
                        type="text"
                        value={emergencyContact}
                        onChange={(e) => setEmergencyContact(e.target.value)}
                        disabled={!isEditing}
                        style={{
                            width: '100%',
                            padding: '10px 0',
                            fontSize: isEasyMode ? '32px' : '20px',
                            border: 'none',
                            borderBottom: isEditing ? '2px solid darkorange' : 'none',
                            backgroundColor: 'transparent',
                            fontWeight: 'bold',
                            color: '#333'
                        }}
                    />
                </div>
            )}

            {/* Edit Button for the Emergency Contact Field */}
            {isEditable && !isEditing && (
                <button
                    onClick={() => setIsEditing(true)}
                    style={{
                        position: 'absolute',
                        top: '15px',
                        right: '15px',
                        padding: '5px 10px',
                        fontSize: isEasyMode ? '20px' : '12px',
                        backgroundColor: '#1A73E8',
                        color: 'white',
                        border: 'none',
                        borderRadius: '5px',
                    }}
                >
                    EDIT ✍️
                </button>
            )}
        </div>
    );
    // --- END FINAL InfoCard ---

    return (
        <div style={{ padding: '0', textAlign: 'center' }}> {/* Removed left/right padding */}
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '30px 0 20px 0', color: '#333', padding: '0 20px' }}>
                Personal Details
            </h2>

            {/* Container now renders list items edge-to-edge */}
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
                {/* Non-Editable Fields */}
                <InfoCard title="Name" value={profile.name} isEasyMode={isEasyMode}/>
                <InfoCard title="IC Number" value={profile.icNumber} isEasyMode={isEasyMode}/>
                <InfoCard title="Date of Birth" value={profile.dateOfBirth} isEasyMode={isEasyMode}/>
                <InfoCard title="Address" value={profile.address} isEasyMode={isEasyMode}/>

                {/* Editable Field */}
                <InfoCard 
                    title="Emergency Contact" 
                    value={emergencyContact} 
                    isEditable={true} 
                    isEasyMode={isEasyMode}
                />

                {/* Save Button (Only Visible when Editing) */}
                {isEditing && (
                    <button
                        onClick={handleSaveContact}
                        style={{
                            padding: '18px 35px', 
                            fontSize: isEasyMode ? '30px' : '20px', 
                            backgroundColor: 'darkorange',
                            color: 'white',
                            border: 'none',
                            borderRadius: '10px',
                            marginTop: '30px',
                            marginBottom: '40px',
                            fontWeight: 'bold',
                        }}
                    >
                        SAVE CHANGES ✅
                    </button>
                )}
            </div>
        </div>
    );
}

export default ProfilePage;
